        :root { --bg: #f0f4f8; --grid: #cbd5e0; --start: #48bb78; --end: #ed8936; --obs: #68d391; }
        body { font-family: sans-serif; background: var(--bg); display: flex; flex-direction: column; align-items: center; padding: 20px; margin: 0; }
