            charB.innerText = "🧥";
            statusB.innerText = "推荐：羽绒服 (合适)";
            statusB.className = "status success";
        }
    }

    slider.addEventListener('input', updateUI);
    testBtn.addEventListener('click', runTest);
</script>

</body>
</html>", "visual_aid_urls": [], "priority": 0.72}, {"id": "V3-2", "content": "如果这家餐厅是一家‘VIP单人餐厅’，里面**有且仅有1号桌**。那么，‘直达1号桌算法（1步）’和‘任意桌通用算法（5步）’相比，此时哪一个更优秀？为什么？", "question_type": "variant", "lesson_presentation_script": "我们刚刚一致认为通用算法更好，对不对？但是，如果现在餐厅老板重新装修了，把其他桌子都拆了，整个餐厅只留下了1号桌。在这个极端的场景下，你还会选那个有5个步骤、还要进行判断和循环的通用算法吗？请大家开动脑筋，想一想：当我们的任务变得绝对单一时，‘通用性’还是最首要的考虑因素吗？", "explanation": "【参考答案】此时直达1号桌算法更优秀。因为在“只有1号桌”的限定场景下，通用算法多出来的判断和规划步骤变成了冗余，增加了不必要的运行代价；而1步直达算法既简单又高效，代价最低，完美契合该特定场景。
【解题思路】引导学生结合特定的场景约束进行辩证分析，理解算法的优劣是相对的，取决于实际应用场景的边界条件。
【易错点提醒】学生容易形成思维定势，由于上一题刚强调了通用性好，这一题仍机械地选择通用算法，无法根据场景条件的彻底改变而转变评价标准。", "knowledge_points": ["KP2"], "cognitive_level": "分析", "difficulty": 0.68, "main_id": "M3", "parent_id": "M3", "variation_type": "", "design_intent": "通过极端条件反转，引导学优生进行辩证思考：没有绝对好的算法维度，当应用场景被限定死之后，特化算法反而比通用算法更具优势，避免陷入对“通用性”的盲目崇拜。", "design_rationale": "", "visual_aid_urls": [], "priority": 0.76}, {"id": "V4-1", "content": "手机充电有两种算法。算法一：‘超级快充’，15分钟充满，但手机发热严重，对电池寿命有微小损伤；算法二：‘普通慢充’，2小时充满，不发热且能保护电池。在‘你马上要出门且手机只剩5%电’和‘晚上睡觉前充电’这两个场景下，你会分别如何选择？请说明理由。", "question_type": "variant", "lesson_presentation_script": "我们在餐厅里当了回精明的经理。现在，回到我们自己的生活中。大家都给手机充过电吧？大屏幕上的这两种充电算法，一个追求‘极速但有微小损伤’，一个追求‘温和但耗时久’。当我们马上要出门和准备睡觉时，我们的时间紧迫度是一样的吗？请大家在小组里讨论一下，在这两种情况下，你会怎么给手机选择充电模式？", "explanation": "【参考答案】出门前选择“超级快充”，因为此时时间极度紧迫，快速获取电量是主要矛盾，电池寿命的微小损伤是可以接受的代价；睡觉前选择“普通慢充”，因为整晚时间充足，没有时间压力，此时保护电池寿命、减少发热（降低代价）成为主要目标。
【解题思路】引导学生分析不同生活场景的核心需求（时间紧迫度），将需求与算法的特征（高效率高能耗 vs 低效率低能耗）进行匹配决策。
